import {matchesOrder} from './core.js';
import {icon,esc,button,audioButton,companion,showDialog,stopAudio} from './ui.js';
function header(p,title,label){return `<div class="activity"><div class="activity-top"><a class="text-button" href="#reading">${icon('back')} Guardar y salir</a><span class="pill">${label}</span></div><section class="activity-card"><span class="eyebrow">LEO Y DESCUBRO</span><h1>${esc(title)}</h1>`;}
function end(text){return `</section>${companion(text)}</div>`;}
function feedback(p){return p.feedback?`<div class="feedback ${p.correct?'success':''}" role="status"><strong>${p.correct?(p.solutionShown?'Vamos a entenderlo juntas.':p.errors?'¡Has vuelto a probar!':'¡Has encontrado la pista!'):'Vamos a mirarlo con calma.'}</strong><p>${esc(p.feedback)}</p>${!p.correct?button('Ver la solución paso a paso','read-solution','secondary small'):button('Continuar '+icon('arrow'),'read-next','small')}</div>`:'';}
function choices(q,p){return `<div class="choices">${q.options.map((o,i)=>`<button class="choice" data-action="read-answer" data-value="${i}" aria-pressed="${p.correct&&i===q.answer}" ${p.correct?'disabled':''}>${esc(o)}</button>`).join('')}</div>`;}
function orderMarkup(items,p,isEvents=false){const order=p.order||[];const bank=p.bank||items.map((_,i)=>i).reverse();return `<p class="muted">Toca en orden. Para cambiarlo, toca una pieza que ya hayas colocado.</p><div class="ordered" aria-label="Tu orden">${order.length?order.map((idx,i)=>`<button data-action="unorder" data-value="${i}" class="${isEvents?'order-event':''} ${p.solutionShown?'reveal-step':''}" style="--i:${i}" ${p.correct?'disabled':''}>${isEvents?(i+1)+'. ':''}${esc(items[idx])}</button>`).join(''):'Tu frase empieza aquí…'}</div><div class="wordbank">${bank.filter(i=>!order.includes(i)).map(i=>`<button data-action="order" data-value="${i}" class="${isEvents?'order-event':''}" ${p.correct?'disabled':''}>${esc(items[i])}</button>`).join('')}</div>${button('Comprobar','read-check-order','',order.length!==items.length||p.correct?'disabled':'')}`;}
function sentenceMarkup(text,i){return `<div class="sentence" id="sentence-${i}"><button class="icon-button sentence-audio" data-action="sentence-audio" data-value="${i}" aria-label="Escuchar frase ${i+1}">${icon('sound')}</button>${text.split(/\s+/).map(w=>`<button class="word" data-action="word" data-word="${esc(w)}" aria-label="Escuchar y consultar ${esc(w.replace(/[.,¿?¡!—]/g,''))}">${esc(w)}</button>`).join(' ')}</div>`;}
export function renderReading(ctx){const p=ctx.state.pending;
 if(p.kind==='story'){const s=ctx.reading.stories.find(x=>x.id===p.id);p.title=s.title;let body='';let label='Antes de leer';
 if(p.stage===0)body=`<p class="instruction">${esc(s.intro)}</p>${audioButton(s.intro)}<div class="notice">Piensa en tu idea o coméntala con alguien. Después comprobaremos qué sucede en el texto.</div>${button('Abrir la historia '+icon('arrow'),'story-stage')}`;
 else if(p.stage===1){label='Leo, escucho y vuelvo a leer';body=`<p class="instruction">Lee una frase. Escucha su modelo y vuelve a leerla a tu manera.</p>${audioButton('Lee una frase. Escucha su modelo y vuelve a leerla. Toca cualquier palabra si necesitas ayuda.')}<div class="spacer">${s.sentences.map(sentenceMarkup).join('')}</div><div class="notice"><strong>Una pausa para pensar</strong><p>${esc(s.during)}</p>${audioButton(s.during)}</div><p class="audio-note">El amarillo marca la frase que suena. Si no hay voz disponible, podéis leerla juntos. No se usa micrófono.</p><div class="row spacer">${button('He vuelto a leer '+icon('check'),'story-stage')}${button('Escuchar el cuento','story-audio','secondary')}</div>`;}
 else if(p.stage===2){label='Una mirada en compañía';body=`<p class="instruction">¿Quieres que un adulto anote cómo fue la lectura?</p><p>Haber leído ya es práctica. Esta anotación no es una prueba de pronunciación.</p><div class="stack">${button('Adulto: leyó sin ayuda','observe','secondary','data-value="independent"')}${button('Adulto: necesitó ayuda','observe','secondary','data-value="supported"')}${button('Seguir sin anotación','observe','','data-value="unobserved"')}</div>`;}
 else if(p.stage>=3&&p.stage<3+s.questions.length){label=`Comprendo · ${p.stage-2} de ${s.questions.length}`;const q=s.questions[p.stage-3];body=`<p class="instruction">${esc(q.prompt)}</p>${audioButton(q.prompt)}${choices(q,p)}<div class="row spacer">${button(icon('book')+' Volver al texto','show-story','secondary small')}${button(icon('help')+' Una pista','read-hint','soft small')}</div>${feedback(p)}`;}
 else{label='¿Qué pasó primero?';body=`<p class="instruction">Ordena los tres acontecimientos del cuento.</p>${audioButton('Toca primero lo que ocurrió al principio, después lo que pasó a continuación y por último lo que sucedió al final.')}${orderMarkup(s.events,p,true)}<div class="row spacer">${button('Volver al texto','show-story','secondary small')}${button('Una pista','read-hint','soft small')}</div>${feedback(p)}`;}
 return header(p,s.title,label)+body+end('Leer otra vez puede ayudarte a descubrir algo nuevo.');
 }
 const a=ctx.reading.phraseActivities.find(x=>x.id===p.id);p.title=a.title;let body=`<p class="instruction">${esc(a.prompt)}</p>${audioButton(a.prompt)}`;
 if(a.type==='order')body+=orderMarkup(a.tokens,p);
 else body+=`${a.sentence?`<div class="sentence">${esc(a.sentence)} ${audioButton(a.sentence.replace('___','espacio'))}</div>`:''}${choices(a,p)}`;
 body+=`<div class="row spacer">${button(icon('help')+' Una pista','read-hint','soft small')}</div>${feedback(p)}`;
 return header(p,a.title,{order:'Construyo una frase',complete:'Busco el sentido',intonation:'Leo con expresión',sound:'Letras y sonidos'}[a.type])+body+end('Mira todas las letras y escucha cómo se unen. Después vuelve a leer.');
}
function current(ctx){const p=ctx.state.pending;if(p.kind==='phrase')return ctx.reading.phraseActivities.find(x=>x.id===p.id);const s=ctx.reading.stories.find(x=>x.id===p.id);return p.stage>=3&&p.stage<3+s.questions.length?s.questions[p.stage-3]:{events:s.events,hint:'Recuerda qué vio o hizo el personaje primero. Luego busca qué cambió.',explanation:s.events.map((e,i)=>`${i+1}. ${e}`).join(' ')};}
function accepted(ctx,solutionShown=false){const p=ctx.state.pending,a=current(ctx);p.correct=true;p.solutionShown=solutionShown;p.help=p.help||solutionShown;p.feedback=a.explanation;ctx.attempt('comprehension',p.kind==='story'?p.id+'-q'+p.stage:p.id,true,{solutionShown,title:p.title});ctx.save();ctx.render();}
function reset(p){p.errors=0;p.help=false;p.correct=false;p.feedback='';p.solutionShown=false;p.order=[];}
export function readingAction(ctx,action,b){const p=ctx.state.pending;if(action==='word'){const original=b.dataset.word;const word=original.toLocaleLowerCase('es').replace(/[^a-záéíóúüñ]/g,'');const d=ctx.reading.words[word];p.help=true;ctx.save();showDialog(`<h2>${esc(original.replace(/[.,!?¿¡—]/g,''))}</h2>${audioButton(word)}${d?`<p class="instruction spacer">${esc(d.meaning)}</p>${button('Ver ayuda de sílabas','syllables','secondary',`data-word="${esc(word)}"`)}<div id="syllables"></div>`:`<p class="spacer">Vuelve a leer la frase para pensar qué significa. Si aún tienes dudas, coméntalo con un adulto.</p><p class="muted">Esta palabra no tiene una entrada en nuestro pequeño glosario.</p>`}${p.kind==='story'&&p.stage>=3?button('Volver al cuento','show-story','secondary'):''}`);ctx.speak(word);return true;}
 if(!p||!['story','phrase'].includes(p.kind))return false;
 if(action==='syllables'){const d=ctx.reading.words[b.dataset.word];document.querySelector('#syllables').innerHTML=`<p class="equation" style="font-size:1.8rem;letter-spacing:1px">${esc(d.syllables)}</p><p>Lee cada parte y luego la palabra entera.</p>`;return true;}
 if(action==='story-stage'){stopAudio();p.stage++;ctx.save();ctx.render();}
 else if(action==='observe'){ctx.attempt('reading',p.id,null,{observation:b.dataset.value,title:p.title,help:b.dataset.value==='supported'||p.help});p.stage=3;reset(p);ctx.save();ctx.render();}
 else if(action==='sentence-audio'){p.help=true;ctx.save();const s=ctx.reading.stories.find(x=>x.id===p.id);ctx.speak(s.sentences[+b.dataset.value],document.querySelector('#sentence-'+b.dataset.value));}
 else if(action==='story-audio'){p.help=true;ctx.save();playStory(ctx,0);}
 else if(action==='show-story'){p.help=true;ctx.save();const s=ctx.reading.stories.find(x=>x.id===p.id);showDialog(`<h2>${esc(s.title)}</h2>${s.sentences.map(sentenceMarkup).join('')}`);}
 else if(action==='read-hint'){p.help=true;const a=current(ctx);p.feedback=a.hint||'Vuelve al texto. Busca la frase que habla de la pregunta; léela despacio.';ctx.save();ctx.render();}
 else if(action==='order'){p.order||=[];p.order.push(+b.dataset.value);p.feedback='';ctx.save();ctx.render();}
 else if(action==='unorder'){p.order.splice(+b.dataset.value,1);p.feedback='';ctx.save();ctx.render();}
 else if(action==='read-check-order'){const a=current(ctx);const okay=a.events?p.order.every((v,i)=>v===i):matchesOrder(p.order.map(i=>a.tokens[i]),a.solutions);if(okay)accepted(ctx);else{p.errors++;p.feedback=a.hint||'Empieza por lo que ocurrió primero. Puedes tocar las piezas para cambiarlas.';ctx.save();ctx.render();}}
 else if(action==='read-answer'){if(p.correct)return true;const a=current(ctx);if(+b.dataset.value===a.answer)accepted(ctx);else{p.errors++;p.feedback=a.hint||'Busca en el texto quién actúa y qué hace. Puedes volver a leer antes de elegir.';ctx.save();ctx.render();}}
 else if(action==='read-solution'){const a=current(ctx);if(a.events)p.order=a.events.map((_,i)=>i);else if(a.tokens){const remaining=a.tokens.map((_,i)=>i);p.order=a.solutions[0].map(t=>{const i=remaining.find(i=>a.tokens[i]===t);remaining.splice(remaining.indexOf(i),1);return i;});}accepted(ctx,true);}
 else if(action==='read-next'){if(p.kind==='phrase')ctx.finish();else{const s=ctx.reading.stories.find(x=>x.id===p.id);if(p.stage>=3+s.questions.length)ctx.finish();else{p.stage++;reset(p);ctx.save();ctx.render();}}}
 else return false;return true;
}
function playStory(ctx,index){const p=ctx.state.pending;if(p?.kind!=='story'||p.stage!==1)return;const s=ctx.reading.stories.find(x=>x.id===p.id);if(index>=s.sentences.length)return;ctx.speak(s.sentences[index],document.querySelector('#sentence-'+index),()=>{if(ctx.state.pending===p&&p.stage===1)playStory(ctx,index+1);});}
